static const float Near = .1, Far = 64, Focal = 1.8;
void               basis(out float3 r, out float3 u, out float3 f)
{
    float sy = sin(aa[2].x), cy = cos(aa[2].x), sp = sin(aa[2].y), cp = cos(aa[2].y);
