{
    uint   tested;
    float3 c     = shade(p, n, base, mat, pixel, tested);
    uint   debug = (uint)aa[0].w;
    if (debug == 1)
        return float4(base, 1);
    if (debug == 2)
        return float4(n * .5 + .5, 1);
    if (debug == 3)
        return float4(saturate(view(p).z / Far).xxx, 1);
    if (debug == 4)
